effect.shader:
#define PI 3.14159265359
float getLuma(vec3 c) {
return dot(c, vec3(0.299, 0.587, 0.114));
}
vec3 rainbowPal(float t) {
vec3 a = vec3(0.5, 0.5, 0.5);
vec3 b = vec3(0.5, 0.5, 0.5);
vec3 c = vec3(1.0, 1.0, 1.0);
vec3 d = vec3(0.0, 0.33, 0.67);
return a + b * cos(2.0 * PI * (c * t + d));
}
void main() {
vec2 uv = acScreenNorm;
vec4 src = texture2DCv(inputImg.texture, uv);
vec2 texel = 1.0 / max(acScreenSize, vec2(1.0));
float aspect = acScreenSize.x / max(acScreenSize.y, 1.0);
vec2 p = uv * vec2(aspect, 1.0);
float t = acTime * fluidSpeed;
float waveX = sin(p.y * waveScale + t) * cos(p.x * waveScale * 0.7 - t * 0.8) * 0.015;
float waveY = cos(p.x * waveScale + t * 0.9) * sin(p.y * waveScale * 0.8 + t * 0.7) * 0.015;
vec2 sampUv = uv + vec2(waveX, waveY);
float hC = getLuma(texture2DCv(inputImg.texture, sampUv).rgb);
float hR = getLuma(texture2DCv(inputImg.texture, sampUv + vec2(texel.x * 2.0, 0.0)).rgb);
float hL = getLuma(texture2DCv(inputImg.texture, sampUv - vec2(texel.x * 2.0, 0.0)).rgb);
float hT = getLuma(texture2DCv(inputImg.texture, sampUv + vec2(0.0, texel.y * 2.0)).rgb);
float hB = getLuma(texture2DCv(inputImg.texture, sampUv - vec2(0.0, texel.y * 2.0)).rgb);
vec3 normal = normalize(vec3((hL - hR) * reliefDepth, (hB - hT) * reliefDepth, 0.35));
float rad = lightAngle * 0.0174532925;
vec3 lightDir = normalize(vec3(cos(rad), sin(rad), 0.75));
vec3 viewDir = vec3(0.0, 0.0, 1.0);
vec3 halfDir = normalize(lightDir + viewDir);
float NdotL = max(dot(normal, lightDir), 0.0);
float specPower = mix(16.0, 128.0, polish);
float NdotH = max(dot(normal, halfDir), 0.0);
float specular = pow(NdotH, specPower) * (1.0 + polish * 2.0);
vec3 refVec = reflect(-viewDir, normal);
float envFresnel = pow(1.0 - max(dot(normal, viewDir), 0.0), 2.5);
vec3 envColor = mix(vec3(0.12, 0.15, 0.2), vec3(0.85, 0.9, 0.95), refVec.y * 0.5 + 0.5);
envColor += pow(max(refVec.y, 0.0), 4.0) * vec3(0.4, 0.45, 0.5);
float iridPhase = (normal.x + normal.y) * iridBands + t * 0.2;
vec3 rainbow = rainbowPal(iridPhase) * iridAmount;
vec3 chromeBase = mix(envColor, chromeColor.rgb, 0.5);
vec3 metalRgb = (chromeBase * (NdotL * 0.5 + 0.5) + rainbow + vec3(specular)) * (1.0 + envFresnel * 0.6);
vec4 result;
if (blendMode == 0) {
result = vec4(metalRgb, src.a);
} else if (blendMode == 1) {
vec3 overlay = mix(2.0 * src.rgb * metalRgb, 1.0 - 2.0 * (1.0 - src.rgb) * (1.0 - metalRgb), step(0.5, src.rgb));
result = vec4(overlay, src.a);
} else if (blendMode == 2) {
result = vec4(1.0 - (1.0 - src.rgb) * (1.0 - metalRgb), src.a);
} else {
result = vec4(src.rgb + metalRgb, src.a);
}
result = clamp(result, 0.0, 1.0);
gl_FragColor = mix(src, result, alpha);
}
